	}

	// 补齐 seq2@12：两条买单各变 60，第一条生效即超限，撤 b2 后仍 60 ≤ 100；
	// 接着 seq3@20：b1 变 100 恰好等于上限，保留。
	mustQuote(t, e, "A", Quote{Seq: 2, Moment: 2, Price: 12}, 2)
	if o, _ := e.Order(b2); o.Status != StatusCanceled {
